import pytest
from event_packet import EventPacket
from sequencer import sequence_stream_batch

def test_stream_sequencing():
    # Test case to reproduce STRM-308
    p1 = EventPacket("s1", 5, "payload1")
    p2 = EventPacket("s2", 5, "payload2")  # Same severity, different stream_id
    result = sequence_stream_batch([p1, p2])

    # Should maintain deterministic order based on stream_id
    assert result[0].stream_id == "s1"  # s1 comes before s2 lexicographically
    assert result[1].stream_id == "s2"
